files.content:
body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #b0b0b0;
  font-family: 'Courier New', monospace;
}

.calculator {
  background: #e0e0e0;
  border: 4px solid #000;
  box-shadow: 8px 8px 0 #000;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 260px;
}

h1 {
  margin: 0 0 8px;
  font-size: 1.5rem;
  text-align: center;
  text-transform: uppercase;
  letter-spacing: 2px;
}

label {
  font-weight: bold;
  font-size: 0.8rem;
  margin-top: 4px;
}

input, select, button, output {
  width: 100%;
  box-sizing: border-box;
  border: 2px solid #000;
  box-shadow: 3px 3px 0 #000;
  background: #fff;
  font-family: inherit;
  font-size: 1rem;
  padding: 6px 8px;
  outline: none;
}

input:focus, select:focus, button:focus, output:focus {
  outline: 3px dashed #ff0;
  outline-offset: 1px;
}

button {
  background: #f0a0a0;
  cursor: pointer;
  font-weight: bold;
  margin-top: 8px;
}

button:active {
  box-shadow: 1px 1px 0 #000;
  transform: translate(2px, 2px);
}

output {
  background: #000;
  color: #0f0;
  font-size: 1.2rem;
  font-weight: bold;
  text-align: right;
}

const leftInput = document.getElementById('left');
const rightInput = document.getElementById('right');
const operationSelect = document.getElementById('operation');
const calculateButton = document.getElementById('calculate');
const resultOutput = document.getElementById('result');

function calculate() {
  const leftRaw = leftInput.value.trim();
  const rightRaw = rightInput.value.trim();
  const operation = operationSelect.value;

  // Reject empty inputs
  if (leftRaw === '' || rightRaw === '') {
    resultOutput.textContent = 'Error';
    return;
  }

  const left = Number(leftRaw);
  const right = Number(rightRaw);

  // Reject non-finite numbers
  if (!Number.isFinite(left) || !Number.isFinite(right)) {
    resultOutput.textContent = 'Error';
    return;
  }

  let result;
  switch (operation) {
    case 'add':
      result = left + right;
      break;
    case 'subtract':
      result = left - right;
      break;
    case 'multiply':
      result = left * right;
      break;
    case 'divide':
      if (right === 0) {
        resultOutput.textContent = 'Error';
        return;
      }
      result = left / right;
      break;
    default:
      resultOutput.textContent = 'Error';
      return;
  }

  resultOutput.textContent = String(result);
}

calculateButton.addEventListener('click', calculate);

// Initialize result to 0
resultOutput.textContent = '0';
